public class Main {

    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0;
        private int buflen = 0;

        private boolean hasNextByte() {
            if (ptr < buflen) return true;
            ptr = 0;
            try {
                buflen = in.read(buffer);
            } catch (IOException e) {
                e.printStackTrace();
            }
            return buflen > 0;
        }

        private int readByte() {
            if (hasNextByte()) return buffer[ptr++];
            else return -1;
        }

        public int nextInt() {
            int b = readByte();
            while (b <= ' ' && b != -1) b = readByte();
            if (b == -1) return -1;
            int res = 0;
            while (b >= '0' && b <= '9') {
                res = res * 10 + (b - '0');
                b = readByte();
            }
            return res;
        }
    }

    static int findCenter(int n, int[][] adj, int[] head, int[] next, int[] to) {
        if (n == 1) return 1;

        int[] dist = new int[n + 1];
        int[] parent = new int[n + 1];
        Queue<Integer> q = new ArrayDeque<>();

        // 1st BFS from node 1
        Arrays.fill(dist, -1);
        dist[1] = 0;
        q.add(1);
        int farNode = 1;

        while (!q.isEmpty()) {
            int u = q.poll();
            if (dist[u] > dist[farNode]) {
                farNode = u;
            }
            for (int e = head[u]; e != -1; e = next[e]) {
                int v = to[e];
                if (dist[v] == -1) {
                    dist[v] = dist[u] + 1;
                    q.add(v);
                }
            }
        }

        // 2nd BFS from farNode
        Arrays.fill(dist, -1);
        Arrays.fill(parent, -1);
        dist[farNode] = 0;
        q.add(farNode);
        int otherEnd = farNode;

        while (!q.isEmpty()) {
            int u = q.poll();
            if (dist[u] > dist[otherEnd]) {
                otherEnd = u;
            }
            for (int e = head[u]; e != -1; e = next[e]) {
                int v = to[e];
                if (dist[v] == -1) {
                    dist[v] = dist[u] + 1;
                    parent[v] = u;
                    q.add(v);
                }
            }
        }

        // Reconstruct path
        ArrayList<Integer> path = new ArrayList<>();
        int curr = otherEnd;
        while (curr != -1) {
            path.add(curr);
            curr = parent[curr];
        }

        return path.get(path.size() / 2);
    }

